input.contents:
# Live status board for D: copy + C: profile backup
$ErrorActionPreference = "SilentlyContinue"
$host.UI.RawUI.WindowTitle = "Backup STATUS board  |  E:\windows backup"
$dest = "E:\windows backup"
$statusFile = "$dest\logs\d-drive-STATUS.txt"

function Get-TreeGB([string]$Path) {
  if (-not (Test-Path -LiteralPath $Path)) { return 0 }
  $s = (Get-ChildItem -LiteralPath $Path -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum
  if (-not $s) { return 0 }
  [math]::Round($s/1GB, 2)
}

function Get-RoboJobs {
  Get-CimInstance Win32_Process -Filter "Name='Robocopy.exe'" | ForEach-Object {
    $cl = $_.CommandLine
    if ($cl -notmatch 'windows backup') { return }
    if ($cl -match 'D:\\') { return "D: full drive" }
    if ($cl -match 'C:\\Users\\store\\([^\s"]+)') { return "C: $($Matches[1])" }
    if ($cl -match 'C:\\Android') { return "C: Android" }
    "robocopy"
  }
}

while ($true) {
  Clear-Host
  $now = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
  Write-Host "============================================================" -ForegroundColor Cyan
  Write-Host "  E:\windows backup  STATUS  ·  $now" -ForegroundColor Cyan
  Write-Host "============================================================" -ForegroundColor Cyan
  Write-Host ""

  $eFree = [math]::Round((Get-PSDrive E).Free/1GB, 1)
  $dUsed = [math]::Round((Get-PSDrive D).Used/1GB, 1)
  Write-Host ("  E: free {0} GB     D: used {1} GB (source)" -f $eFree, $dUsed)

  Write-Host ""
  Write-Host "  Active robocopy:" -ForegroundColor Yellow
  $jobs = @(Get-RoboJobs)
  if ($jobs.Count -eq 0) { Write-Host "    (none right now)" -ForegroundColor DarkGray }
  else { $jobs | ForEach-Object { Write-Host "    · $_" } }

  Write-Host ""
  Write-Host "  Destination sizes (GB):" -ForegroundColor Yellow
  Write-Host ("    C\Users\store : {0}" -f (Get-TreeGB "$dest\C\Users\store"))
  Write-Host ("    C\Android     : {0}" -f (Get-TreeGB "$dest\C\Android"))
  Write-Host ("    D\            : {0}" -f (Get-TreeGB "$dest\D"))

  Write-Host ""
  Write-Host "  D-drive status file (last 8 lines):" -ForegroundColor Yellow
  if (Test-Path -LiteralPath $statusFile) {
    Get-Content -LiteralPath $statusFile -Tail 8 | ForEach-Object { Write-Host "    $_" }
  } else {
    Write-Host "    (waiting for copy to start…)" -ForegroundColor DarkGray
  }

  $fin = Test-Path "$dest\logs\d-drive-FINISHED.txt"
  $cFin = Test-Path "$dest\logs\FINISHED.txt"
  Write-Host ""
  Write-Host ("  D copy finished: {0}     C script finished: {1}" -f $fin, $cFin) -ForegroundColor $(if ($fin) { "Green" } else { "DarkGray" })
  Write-Host ""
  Write-Host "  Refresh every 15s  ·  Ctrl+C to stop board (copy keeps running)" -ForegroundColor DarkGray

  if ($fin -and -not $jobs) {
    Write-Host ""
    Write-Host "  All quiet — D copy done. Press Ctrl+C or close window." -ForegroundColor Green
  }
  Start-Sleep -Seconds 15
}

# Live status board for D: copy + C: profile backup (ASCII-only for Windows PowerShell 5.1)
$ErrorActionPreference = "SilentlyContinue"
$Host.UI.RawUI.WindowTitle = "Backup STATUS board | E:\windows backup"
$dest = "E:\windows backup"
$statusFile = Join-Path $dest "logs\d-drive-STATUS.txt"

function Get-TreeGB([string]$Path) {
  if (-not (Test-Path -LiteralPath $Path)) { return 0 }
  $s = (Get-ChildItem -LiteralPath $Path -Recurse -Force -File -ErrorAction SilentlyContinue |
    Measure-Object Length -Sum).Sum
  if (-not $s) { return 0 }
  [math]::Round($s / 1GB, 2)
}

function Get-RoboJobs {
  Get-CimInstance Win32_Process -Filter "Name='Robocopy.exe'" | ForEach-Object {
    $cl = $_.CommandLine
    if ($cl -notmatch 'windows backup') { return }
    if ($cl -match 'D:\\') { return "D: full drive" }
    if ($cl -match 'C:\\Users\\store\\([^\s"]+)') { return "C: $($Matches[1])" }
    if ($cl -match 'C:\\Android') { return "C: Android" }
    "robocopy"
  }
}

while ($true) {
  Clear-Host
  $now = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
  Write-Host "============================================================" -ForegroundColor Cyan
  Write-Host "  E:\windows backup  STATUS  -  $now" -ForegroundColor Cyan
  Write-Host "============================================================" -ForegroundColor Cyan
  Write-Host ""

  $eFree = [math]::Round((Get-PSDrive E).Free / 1GB, 1)
  $dUsed = [math]::Round((Get-PSDrive D).Used / 1GB, 1)
  Write-Host ("  E: free {0} GB     D: used {1} GB (source)" -f $eFree, $dUsed)

  Write-Host ""
  Write-Host "  Active robocopy:" -ForegroundColor Yellow
  $jobs = @(Get-RoboJobs)
  if ($jobs.Count -eq 0) {
    Write-Host "    (none right now)" -ForegroundColor DarkGray
  }
  else {
    $jobs | ForEach-Object { Write-Host "    - $_" }
  }

  Write-Host ""
  Write-Host "  Destination sizes (GB):" -ForegroundColor Yellow
  Write-Host ("    C\Users\store : {0}" -f (Get-TreeGB (Join-Path $dest "C\Users\store")))
  Write-Host ("    C\Android     : {0}" -f (Get-TreeGB (Join-Path $dest "C\Android")))
  Write-Host ("    D\            : {0}" -f (Get-TreeGB (Join-Path $dest "D")))

  Write-Host ""
  Write-Host "  D-drive status file (last 8 lines):" -ForegroundColor Yellow
  if (Test-Path -LiteralPath $statusFile) {
    Get-Content -LiteralPath $statusFile -Tail 8 | ForEach-Object { Write-Host "    $_" }
  }
  else {
    Write-Host "    (waiting for copy to start...)" -ForegroundColor DarkGray
  }

  $fin = Test-Path (Join-Path $dest "logs\d-drive-FINISHED.txt")
  $cFin = Test-Path (Join-Path $dest "logs\FINISHED.txt")
  Write-Host ""
  $finColor = if ($fin) { "Green" } else { "DarkGray" }
  Write-Host ("  D copy finished: {0}     C script finished: {1}" -f $fin, $cFin) -ForegroundColor $finColor
  Write-Host ""
  Write-Host "  Refresh every 15s  -  Ctrl+C to stop board (copy keeps running)" -ForegroundColor DarkGray

  if ($fin -and -not $jobs) {
    Write-Host ""
    Write-Host "  All quiet - D copy done. Press Ctrl+C or close window." -ForegroundColor Green
  }
  Start-Sleep -Seconds 15
}

input.command:
# Validate parse, then reopen status board
$err = $null
$null = [System.Management.Automation.Language.Parser]::ParseFile(
  'E:\windows backup\logs\status-board.ps1',
  [ref]$null,
  [ref]$err
)
if ($err) { Write-Output "PARSE FAIL:"; $err | ForEach-Object { $_.ToString() }; exit 1 }
Write-Output "PARSE OK"

# Kill old status board if still around (PID from pids file or title)
$pidsFile = 'E:\windows backup\logs\d-drive-pids.txt'
if (Test-Path $pidsFile) {
  $txt = Get-Content $pidsFile -Raw
  if ($txt -match 'boardPid=(\d+)') {
    $bp = [int]$Matches[1]
    Stop-Process -Id $bp -Force -ErrorAction SilentlyContinue
    "stopped old board $bp"
  }
}

$board = Start-Process -FilePath "powershell.exe" -ArgumentList @(
  "-NoProfile","-ExecutionPolicy","Bypass","-NoExit","-File",
  "E:\windows backup\logs\status-board.ps1"
) -WorkingDirectory "E:\windows backup\logs" -WindowStyle Normal -PassThru
Write-Output "New STATUS board PID=$($board.Id)"

# Confirm D copy still running
Get-CimInstance Win32_Process -Filter "Name='Robocopy.exe'" | ForEach-Object {
  if ($_.CommandLine -match 'D:\\.*"E:\\windows backup\\D"') { "D robocopy ALIVE pid=$($_.ProcessId)" }
}
if (Test-Path 'E:\windows backup\logs\d-drive-STATUS.txt') {
  Get-Content 'E:\windows backup\logs\d-drive-STATUS.txt' -Tail 5
}

$dest = 'E:\windows backup'
Write-Output "=== C backup process ==="
$pidLine = Get-Content "$dest\logs\backup-pid.txt" -ErrorAction SilentlyContinue
Write-Output $pidLine
if ($pidLine -match 'PID=(\d+)') {
  $p = Get-Process -Id ([int]$Matches[1]) -ErrorAction SilentlyContinue
  if ($p) { "powershell ALIVE  CPU=$([math]::Round($p.CPU,1))  WS_MB=$([math]::Round($p.WorkingSet64/1MB,0))" }
  else { "powershell EXITED" }
}
Write-Output ""
Write-Output "=== active C robocopy ==="
Get-CimInstance Win32_Process -Filter "Name='Robocopy.exe'" | ForEach-Object {
  $cl = $_.CommandLine
  if ($cl -match 'windows backup' -and $cl -match 'C:\\') {
    if ($cl -match 'C:\\Users\\store\\([^\s"]+)') { "C:\$($Matches[1])  pid=$($_.ProcessId)" }
    elseif ($cl -match 'C:\\Android') { "C:\Android  pid=$($_.ProcessId)" }
    else { $cl.Substring(0,[Math]::Min(140,$cl.Length)) }
  }
}
Write-Output ""
Write-Output "=== finished marker ==="
Test-Path "$dest\logs\FINISHED.txt"
if (Test-Path "$dest\logs\FINISHED.txt") { Get-Content "$dest\logs\FINISHED.txt" }

Write-Output ""
Write-Output "=== folders on dest ==="
Get-ChildItem "$dest\C\Users\store" -Force -ErrorAction SilentlyContinue | Select-Object -ExpandProperty Name

Write-Output ""
Write-Output "=== sizes (quick top-level) ==="
function SizeGB($p) {
  if (-not (Test-Path -LiteralPath $p)) { return $null }
  $s = (Get-ChildItem -LiteralPath $p -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum
  [math]::Round(($s/1GB),2)
}
foreach ($n in @('Desktop','Documents','Downloads','Pictures','Videos','Music','RootRecord','.cursor','.cloudflared','.android','.dotnet','.gradle','.nuget','AppData')) {
  $gb = SizeGB "$dest\C\Users\store\$n"
  if ($null -ne $gb) { "{0,-16} {1} GB" -f $n, $gb }
}
$agb = SizeGB "$dest\C\Android"
if ($null -ne $agb) { "{0,-16} {1} GB" -f 'Android', $agb }

Write-Output ""
Write-Output "=== robocopy log tail ==="
$log = Get-ChildItem "$dest\logs\robocopy-*.log" -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 1
if ($log) {
  "log: $($log.Name)  $($log.Length) bytes  $($log.LastWriteTime)"
  Get-Content $log.FullName -Tail 20
}

$log = Get-ChildItem 'E:\windows backup\logs\robocopy-*.log' | Sort-Object LastWriteTime -Descending | Select-Object -First 1
"log=$($log.Name) size=$($log.Length) mtime=$($log.LastWriteTime)"
Select-String -Path $log.FullName -Pattern 'START |DONE exit=' | Select-Object -Last 25 | ForEach-Object { $_.Line }
Write-Output "---"
# fast dir sizes without deep recurse on huge trees - use robocopy /L? or just Measure on known completed
$base = 'E:\windows backup\C\Users\store'
@(
  '.cursor','.cloudflared','.android','.dotnet','.gradle','.nuget','AppData'
) | ForEach-Object {
  $p = Join-Path $base $_
  if (Test-Path $p) {
    $item = Get-Item $p
    # approximate via (Get-ChildItem -Depth 0 count) + whether nonempty
    $files = (cmd /c "dir /s /-c `"$p`" 2>nul" | Select-String 'File\(s\)').Line
    "$_ : $files"
  } else { "$_ : MISSING" }
}
Test-Path 'E:\windows backup\C\Android'
Test-Path 'E:\windows backup\C\Users\store\AppData'

Select-String -Path 'E:\windows backup\logs\robocopy-20260801-175229.log' -Pattern 'START |DONE exit=' | ForEach-Object { $_.Line } | Select-Object -Last 20
Write-Output "---"
Get-CimInstance Win32_Process -Filter "Name='Robocopy.exe'" | ForEach-Object {
  if ($_.CommandLine -match 'C:\\Users\\store\\([^\s"]+)') { "NOW: C:\Users\store\$($Matches[1])" }
  elseif ($_.CommandLine -match 'C:\\Android') { "NOW: C:\Android" }
  elseif ($_.CommandLine -match 'AppData') { "NOW: AppData" }
}

Get-ChildItem "D:\.1 Work Stations\RootMC\Server Handoffs\Ava Ivy\appearance" -Recurse -Force -ErrorAction SilentlyContinue | Select-Object FullName, Length, LastWriteTime | Format-Table -AutoSize
Write-Output "==== image sizes ===="
@('image.jpg','image (1).jpg','image (2).jpg','image (3).jpg','image (4).jpg','videoframe_2794.png','ava-ivy-slack-icon-1024.png') | ForEach-Object {
  $p = "C:\Users\store\Downloads\$_"
  if (Test-Path $p) {
    Add-Type -AssemblyName System.Drawing
    $img = [System.Drawing.Image]::FromFile($p)
    "$_ : $($img.Width)x$($img.Height)"
    $img.Dispose()
  }
}

$ErrorActionPreference = 'SilentlyContinue'
Write-Output "=== C: free/used ==="
Get-PSDrive C | Select-Object @{N='UsedGB';E={[math]::Round($_.Used/1GB,1)}}, @{N='FreeGB';E={[math]::Round($_.Free/1GB,1)}}
Write-Output "=== C:\ root ==="
Get-ChildItem C:\ -Force | ForEach-Object {
  $n = $_.Name
  if ($_.PSIsContainer) {
    # quick top-level size estimate via robocopy /L bytes? too slow — just list
    "DIR  $n"
  } else {
    "FILE $n ($([math]::Round($_.Length/1MB,2)) MB)"
  }
}
Write-Output "=== Users ==="
Get-ChildItem C:\Users -Force | Select-Object Name, Mode
Write-Output "=== store profile (non-junction) ==="
Get-ChildItem 'C:\Users\store' -Force | Where-Object { -not $_.Attributes.ToString().Contains('ReparsePoint') } | ForEach-Object {
  if ($_.PSIsContainer) { "DIR  $($_.Name)" } else { "FILE $($_.Name) ($([math]::Round($_.Length/1KB,1)) KB)" }
}

# AppData Roaming + Local top by rough size (robocopy /L bytes is accurate-ish)
function RoboBytes($src) {
  if (-not (Test-Path -LiteralPath $src)) { return $null }
  $out = robocopy $src $src /L /S /NJH /NJS /NDL /NC /NS /NP /BYTES /NFL 2>$null
  # last lines have Bytes - actually /L with /BYTES prints in summary
  $sum = robocopy $src NULL /L /E /NJH /NJS /NDL /NC /NS /NP /BYTES /NFL /XD 'Temp' 'Cache' 'CachedData' 'Code Cache' 'GPUCache' 2>&1 | Out-String
  # fallback: measure first-level only then sample
  return $null
}
Write-Output "=== AppData\Roaming top dirs ==="
Get-ChildItem 'C:\Users\store\AppData\Roaming' -Directory -Force -ErrorAction SilentlyContinue | ForEach-Object {
  $bytes = 0L
  Get-ChildItem $_.FullName -Recurse -Force -File -ErrorAction SilentlyContinue | ForEach-Object { $bytes += $_.Length }
  [PSCustomObject]@{ Name=$_.Name; GB=[math]::Round($bytes/1GB,2) }
} | Sort-Object GB -Descending | Select-Object -First 25 | Format-Table -AutoSize

Write-Output "=== AppData\Local top dirs ==="
Get-ChildItem 'C:\Users\store\AppData\Local' -Directory -Force -ErrorAction SilentlyContinue | ForEach-Object {
  $bytes = 0L
  # skip Temp for speed? still measure name
  if ($_.Name -eq 'Temp') { [PSCustomObject]@{ Name='Temp (skip deep)'; GB='?' }; return }
  Get-ChildItem $_.FullName -Recurse -Force -File -ErrorAction SilentlyContinue | ForEach-Object { $bytes += $_.Length }
  [PSCustomObject]@{ Name=$_.Name; GB=[math]::Round($bytes/1GB,2) }
} | Sort-Object GB -Descending | Select-Object -First 25 | Format-Table -AutoSize

# AppData Roaming + Local top by rough size (robocopy /L bytes is accurate-ish)
function RoboBytes($src) {
  if (-not (Test-Path -LiteralPath $src)) { return $null }
  $out = robocopy $src $src /L /S /NJH /NJS /NDL /NC /NS /NP /BYTES /NFL 2>$null
  # last lines have Bytes - actually /L with /BYTES prints in summary
  $sum = robocopy $src NULL /L /E /NJH /NJS /NDL /NC /NS /NP /BYTES /NFL /XD 'Temp' 'Cache' 'CachedData' 'Code Cache' 'GPUCache' 2>&1 | Out-String
  # fallback: measure first-level only then sample
  return $null
}
Write-Output "=== AppData\Roaming top dirs ==="
Get-ChildItem 'C:\Users\store\AppData\Roaming' -Directory -Force -ErrorAction SilentlyContinue | ForEach-Object {
  $bytes = 0L
  Get-ChildItem $_.FullName -Recurse -Force -File -ErrorAction SilentlyContinue | ForEach-Object { $bytes += $_.Length }
  [PSCustomObject]@{ Name=$_.Name; GB=[math]::Round($bytes/1GB,2) }
} | Sort-Object GB -Descending | Select-Object -First 25 | Format-Table -AutoSize

Write-Output "=== AppData\Local top dirs ==="
Get-ChildItem 'C:\Users\store\AppData\Local' -Directory -Force -ErrorAction SilentlyContinue | ForEach-Object {
  $bytes = 0L
  # skip Temp for speed? still measure name
  if ($_.Name -eq 'Temp') { [PSCustomObject]@{ Name='Temp (skip deep)'; GB='?' }; return }
  Get-ChildItem $_.FullName -Recurse -Force -File -ErrorAction SilentlyContinue | ForEach-Object { $bytes += $_.Length }
  [PSCustomObject]@{ Name=$_.Name; GB=[math]::Round($bytes/1GB,2) }
} | Sort-Object GB -Descending | Select-Object -First 25 | Format-Table -AutoSize

# What is C backup doing now + Robocopy START/DONE via Select-String ISO dates only
Get-CimInstance Win32_Process -Filter "Name='Robocopy.exe'" | ForEach-Object {
  if ($_.CommandLine -match 'windows backup') {
    if ($_.CommandLine -match 'C:\\Users\\store\\([^\s"]+)') { "C NOW: $($Matches[1])" }
    elseif ($_.CommandLine -match 'C:\\Android') { "C NOW: Android" }
    elseif ($_.CommandLine -match 'AppData') { "C NOW: AppData..." }
    elseif ($_.CommandLine -match 'D:\\') { "D NOW: full drive" }
  }
}
# FileZilla, cloudflared already noted; check Local Programs, Minecraft
@(
  'C:\Users\store\AppData\Roaming\FileZilla',
  'C:\Users\store\AppData\Local\Programs',
  'C:\Users\store\AppData\Local\RootMC',
  'C:\Users\store\AppData\Local\MinecraftLauncher',
  'C:\Users\store\AppData\Local\Packages',
  'C:\ProgramData\ssh'
) | ForEach-Object { "$_ -> $(Test-Path $_)" }
cmd /c "dir /a `"C:\ProgramData\ssh`" 2>nul"
cmd /c "dir /a `"C:\Users\store\AppData\Roaming\FileZilla`" 2>nul"

# Status of background C backup
$pidLine = Get-Content 'E:\windows backup\logs\backup-pid.txt' -EA SilentlyContinue
Write-Output $pidLine
if ($pidLine -match 'PID=(\d+)') {
  $p = Get-Process -Id ([int]$Matches[1]) -EA SilentlyContinue
  if ($p) { "C-script ALIVE" } else { "C-script EXITED" }
}
Get-CimInstance Win32_Process -Filter "Name='Robocopy.exe'" | ForEach-Object {
  if ($_.CommandLine -match 'windows backup') {
    if ($_.CommandLine -match 'C:\\Users\\store\\AppData\\(Roaming|Local)\\([^\s"]+)') { "ROBO AppData\$($Matches[1])\$($Matches[2])" }
    elseif ($_.CommandLine -match 'C:\\Users\\store\\([^\s"]+)') { "ROBO store\$($Matches[1])" }
    elseif ($_.CommandLine -match 'C:\\Android') { "ROBO Android" }
    elseif ($_.CommandLine -match 'D:\\') { "ROBO D:" }
  }
}
Test-Path 'E:\windows backup\C\Users\store\AppData'
Test-Path 'E:\windows backup\logs\FINISHED.txt'

$script = 'E:\windows backup\logs\priority-keep.ps1'
$p = Start-Process -FilePath "powershell.exe" -ArgumentList @(
  "-NoProfile","-ExecutionPolicy","Bypass","-NoExit","-File",$script
) -WorkingDirectory "E:\windows backup\logs" -WindowStyle Normal -PassThru
"priorityPid=$($p.Id)" | Set-Content 'E:\windows backup\logs\priority-pid.txt'
Write-Output "Priority KEEP window PID=$($p.Id)"
Start-Sleep -Seconds 8
Get-Content 'E:\windows backup\logs\priority-STATUS.txt' -EA SilentlyContinue
Get-CimInstance Win32_Process -Filter "Name='Robocopy.exe'" | ForEach-Object {
  if ($_.CommandLine -match 'windows backup') {
    if ($_.CommandLine -match 'Desktop') { "ROBO Desktop" }
    elseif ($_.CommandLine -match 'Downloads') { "ROBO Downloads" }
    elseif ($_.CommandLine -match 'AppData') { "ROBO AppData..." }
    elseif ($_.CommandLine -match '\\.gradle') { "ROBO .gradle (old job)" }
    elseif ($_.CommandLine -match 'D:\\') { "ROBO D:" }
    else { $_.CommandLine.Substring(0,[Math]::Min(100,$_.CommandLine.Length)) }
  }
}

