$dest = "E:\windows backup\D"
$logDir = "E:\windows backup\logs"
New-Item -ItemType Directory -Force -Path $dest, $logDir | Out-Null
$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$log = Join-Path $logDir "d-ensure-$stamp.log"
$status = Join-Path $logDir "d-drive-STATUS.txt"

function Write-Status([string]$msg) {
  $line = "$(Get-Date -Format 'HH:mm:ss')  $msg"
  Write-Host $line
  Add-Content -LiteralPath $status -Value $line -Encoding utf8
}

Write-Host "============================================================" -ForegroundColor Cyan
Write-Host "  ENSURE full D:\  ->  E:\windows backup\D" -ForegroundColor Cyan
Write-Host "============================================================" -ForegroundColor Cyan

# Wait if another D:\ robocopy is already running (don't fight it)
while ($true) {
  $busy = Get-CimInstance Win32_Process -Filter "Name='Robocopy.exe'" | Where-Object {
    $_.CommandLine -match 'D:\\.*"E:\\windows backup\\D"'
  }
  if (-not $busy) { break }
  Write-Status "Waiting for existing D: robocopy (PID $($busy.ProcessId -join ','))..."
  Start-Sleep -Seconds 30
}

Write-Status "Starting ensure robocopy (full D: except Recycle Bin / System Volume Info)"
$sw = [Diagnostics.Stopwatch]::StartNew()
& robocopy "D:\" $dest /E /COPY:DAT /DCOPY:DA /R:2 /W:3 /XJ /MT:16 `
  /XD "`$RECYCLE.BIN" "System Volume Information" `
  /XF "pagefile.sys" "hiberfil.sys" "Swapfile.sys" "DumpStack.log.tmp" `
  /ETA /TEE /LOG+:$log
$code = $LASTEXITCODE
