# Deep-ish inventory of E and D Work Stations (folders + file counts, skip huge caches)
function Inventory-Tree($root, $maxDepth=3) {
  $rows = [System.Collections.Generic.List[object]]::new()
  function Walk($path, $depth) {
    if ($depth -gt $maxDepth) { return }
    try {
      $items = Get-ChildItem -LiteralPath $path -Force -EA SilentlyContinue
    } catch { return }
    foreach ($i in $items) {
      $name = $i.Name
      if ($name -in @('node_modules','.gradle','build','out','.git','Server Live Backups')) {
        $rows.Add([pscustomobject]@{ path = $i.FullName.Replace($root,'').TrimStart('\'); kind = if($i.PSIsContainer){'dir-skipped'}else{'file'}; note = 'excluded from deep count' })
        continue
