          $kids = Get-ChildItem -LiteralPath $i.FullName -Force -File -EA SilentlyContinue
          $fc = @($kids).Count
          $bytes = ($kids | Measure-Object Length -Sum).Sum
          if (-not $bytes) { $bytes = 0 }
        } catch {}
        $rows.Add([pscustomobject]@{
          path = $i.FullName.Replace($root,'').TrimStart('\')
          kind = 'dir'
          files_here = $fc
          size_MB = [math]::Round($bytes/1MB,2)
          depth = $depth
        })
        Walk $i.FullName ($depth+1)
      } else {
        if ($depth -le 2) {
          $rows.Add([pscustomobject]@{
            path = $i.FullName.Replace($root,'').TrimStart('\')
            kind = 'file'
            files_here = 1
            size_MB = [math]::Round($i.Length/1MB,2)
            depth = $depth
          })
        }
      }
    }
  }
  Walk $root 0
  return $rows
}

