function ShowChain($id, $depth=0) {
  $p = Get-CimInstance Win32_Process -Filter "ProcessId=$id" -EA SilentlyContinue
  if (-not $p) { return }
  ('  '*$depth) + "$($p.ProcessId) $($p.Name) :: $($p.CommandLine.Substring(0,[Math]::Min(100, $p.CommandLine.Length)))"
  if ($p.ParentProcessId -and $depth -lt 6) { ShowChain $p.ParentProcessId ($depth+1) }
}
