  const chRes = await fetch(`${DISCORD_API}/channels/${ID}`, { headers });
  if (chRes.ok) {
    const ch = await chRes.json();
    const msgs = await fetch(
      `${DISCORD_API}/channels/${ID}/messages?limit=30`,
      { headers },
    ).then((r) => r.json());
    return { kind: "channel", ch, msgs: Array.isArray(msgs) ? msgs : [] };
  }
  // Search guild channels with around=
  const chans = await fetch(
    `${DISCORD_API}/guilds/${ROOTMC_GUILD_ID}/channels`,
    { headers },
  ).then((r) => r.json());
  const ids = new Set((chans || []).map((c) => c.id));
  const active = await fetch(
    `${DISCORD_API}/guilds/${ROOTMC_GUILD_ID}/threads/active`,
    { headers },
  ).then((r) => (r.ok ? r.json() : { threads: [] }));
